def check_condition(n):
    if n <= 1:
        return False

    # Check if k^2 == 1 (mod n) for all k coprime to n

    # Find all k coprime to n
    coprimes = [k for k in range(1, n) if math.gcd(k, n) == 1]

    for k in coprimes:
        if (k * k) % n != 1:
            return False
    return True

import math
print("Values n <= 20 that satisfy the condition:", [n for n in range(2, 21) if check_condition(n)])
